import re, os

def parse_header_fields(text):
    fields = {}
    for line in text.splitlines():
        m = re.match(r"\*\*([^:*]+):\*\*\s*(.*)", line.strip())
        if m:
            fields[m.group(1).strip()] = m.group(2).strip()
    return fields

combos = set()
for b in ["01","02","03"]:
    d = f"office-exports/batch-{b}/decisions"
    for fn in sorted(os.listdir(d)):
        text = open(os.path.join(d, fn)).read()
        f = parse_header_fields(text)
        combos.add((f.get("Body"), f.get("Outcome"), f.get("Signatory"), f.get("Role"), f.get("Decision date"), fn))

for c in sorted(combos):
    print(c)
